using System.ComponentModel.DataAnnotations;
namespace PublishingReviewApp.DTOs;
public class ProductDto { public int Id {get;set;} public string Name {get;set;}=string.Empty; public string Description {get;set;}=string.Empty; public decimal Price {get;set;} public DateTime CreatedAt {get;set;} public string? ImageUrl {get;set;} public List<int> CategoryIds {get;set;}=new(); public string Categories {get;set;}=string.Empty; public double AverageRating {get;set;} public int ReviewsCount {get;set;} }
public class ProductCreateDto { public int Id {get;set;} [Required,StringLength(150)] public string Name {get;set;}=string.Empty; [StringLength(2000)] public string Description {get;set;}=string.Empty; [Range(0.01,double.MaxValue)] public decimal Price {get;set;} [DataType(DataType.ImageUrl)] public string? ImageUrl {get;set;} public List<int> CategoryIds {get;set;}=new(); }
public class ReviewDto { public int Id {get;set;} public int ProductId {get;set;} public string ProductName {get;set;}=string.Empty; public int UserId {get;set;} public string UserName {get;set;}=string.Empty; public string Text {get;set;}=string.Empty; public DateTime CreatedAt {get;set;} public int? UserRating {get;set;} }
public class ReviewCreateDto { public int Id {get;set;} [Required] public int ProductId {get;set;} [Required,StringLength(1500,MinimumLength=1)] public string Text {get;set;}=string.Empty; [Range(1,5)] public int RatingValue {get;set;}=5; }
public class RatingDto { public int Id {get;set;} public int ProductId {get;set;} public int UserId {get;set;} [Range(1,5)] public int Value {get;set;} public DateTime CreatedAt {get;set;} }
